# Break My Fix finding 2, generated by Tracefix: badge returns a wrong value.
# Property (comment): With message and color but no label the URL path has the two components {message}-{color}
# Quote: Either {message}-{color} or {label}-{message}-{color}
# Run it with pytest: it fails for as long as the code breaks this property.

import re

from clldutils.badge import badge


def test_break_my_fix_2() -> None:
    subject = ''
    status = ''
    color = 'green'
    message = 'X-X'
    label = ''
    fmt = 'svg'
    markdown = False
    # The property applies to this input: markdown == False and fmt == 'svg' and label == '' and message != '' and color != '' and subject == '' and status == '' and '-' not in color and not message.startswith('-') and not message.endswith('-') and '--' not in message
    result = badge(subject=subject, status=status, color=color, message=message, label=label, fmt=fmt, markdown=markdown)
    assert (len(re.split(r'(?<!-)-(?!-)', result.split('?')[0][len('https://img.shields.io/badge/'):-4])) == 2 and re.split(r'(?<!-)-(?!-)', result.split('?')[0][len('https://img.shields.io/badge/'):-4])[-1] == color)
